_BB = {"N", "CA", "C", "O", "OXT"}


def _element_of(name: str) -> str:
    if name.startswith("N"):
        return "N"
    if name.startswith("O") or name.startswith("OH"):
        return "O"
    if name.startswith("S"):
        return "S"
    return "C"


def _fit(src: np.ndarray, dst: np.ndarray):
    sc, dc = src.mean(0), dst.mean(0)
    h = (src - sc).T @ (dst - dc)
    u, _, vt = np.linalg.svd(h)
    r = vt.T @ u.T
    if np.linalg.det(r) < 0:
        vt[-1] *= -1
        r = vt.T @ u.T
    return r, dc - r @ sc


def _rotate_about(points, axis_p, axis_q, angle_deg):
    v = axis_q - axis_p
    v = v / np.linalg.norm(v)
    a = np.radians(angle_deg)
    c, s = np.cos(a), np.sin(a)
    out = []
    for p in points:
        rel = p - axis_p
        out.append(axis_p + rel * c + np.cross(v, rel) * s + v * np.dot(v, rel) * (1 - c))
    return np.array(out)


def place_sidechain(present, aa3, others=None):
    names, coords = _AA_COORDS[aa3]
    ideal = {n: np.asarray(c, np.float64) for n, c in zip(names, coords)}
    bb = [n for n in ("N", "CA", "C") if n in present and n in ideal]
    if len(bb) < 3:
        raise ValueError(f"place_sidechain({aa3}): backbone N/CA/C not all present")
    src = np.stack([ideal[n] for n in bb])
    dst = np.stack([present[n] for n in bb])
    r, t = _fit(src, dst)
    side = {n: (r @ ideal[n] + t) for n in names if n not in _BB}
    if not side:
        return []

    ca = present["CA"]
    cb = side["CB"]
    beyond_cb = [n for n in side if n != "CB"]

    def _gen():
        for chi1 in (0.0, 120.0, 240.0):
            cand = dict(side)
            if chi1 and beyond_cb:
                pts = _rotate_about(np.stack([side[n] for n in beyond_cb]), ca, cb, chi1)
                for n, p in zip(beyond_cb, pts):
                    cand[n] = p
            if "CG" in cand:
                cg = cand["CG"]
                beyond_cg = [n for n in cand if n not in ("CB", "CG")]
                for chi2 in (0.0, 120.0, 240.0):
                    c2 = dict(cand)
                    if chi2 and beyond_cg:
                        pts = _rotate_about(np.stack([cand[n] for n in beyond_cg]), cb, cg, chi2)
                        for n, p in zip(beyond_cg, pts):
                            c2[n] = p
                    yield c2
            else:
                yield cand

    cands = list(_gen())
    if others is None or len(others) == 0:
        best = cands[0]
    else:
        others = np.asarray(others, np.float64).reshape(-1, 3)
        bbpts = np.stack([present[n] for n in ("N", "CA", "C")])
        best, best_score = None, -1.0
        for cand in cands:
            pts = np.stack(list(cand.values()))
            d = np.linalg.norm(pts[:, None, :] - others[None, :, :], axis=2).min()
            d = min(d, np.linalg.norm(pts[:, None, :] - bbpts[None, :, :], axis=2).min())
            if d > best_score:
                best_score, best = d, cand
    return [(n, best[n]) for n in names if n not in _BB]
